INSERT INTO business_research (id, business_name, website, industry, description, problem, decision_maker, personalised_outreach, source_urls, verification_status, verified_facts, assumptions) VALUES
('b0000000-0000-0000-0000-000000000001', 'Customer.io', 'https://customer.io', 'B2B SaaS / Automated Messaging & Customer Data', 'Customer engagement and automated messaging platform for tech companies and modern product teams.', 'High sales engineering capacity waste from mid-market demo no-shows during competitive evaluation against Braze/Iterable.', 'Chris Parker, VP of Global Sales', 'Hi Chris, saw Customer.io expanding its Data Pipelines integration. As sales velocity scales, how is your team handling demo show-up rates for mid-market technical evaluations? We built a lightweight pre-demo qualification workflow that lifts attendance from 38% to 78% by sending dynamic 60-sec architecture briefs. Worth a 5-min look?', ARRAY['https://customer.io/about/', 'https://linkedin.com/in/chrisparker-sales'], 'Verified with Sources', ARRAY['Recent push into Data Pipelines expansion', 'VP Global Sales leading 40+ rep organization', 'High ACV ($15k-$60k)'], ARRAY['Mid-market demo attendance fluctuates around 35-40%']),
('b0000000-0000-0000-0000-000000000002', 'Vanta', 'https://vanta.com', 'B2B SaaS / Automated Security & Compliance', 'Automated security and continuous compliance monitoring platform for SOC 2, ISO 27001, and HIPAA.', 'Severe drop-off between demo booking and attendance among time-strapped CISOs and Heads of Engineering.', 'Stevie Case, Chief Revenue Officer', 'Hi Stevie, scaling Vanta''s enterprise trust platform means AEs are pitching overburdened CISOs whose calendars shift hourly. We automated pre-demo verification loops that reduced compliance demo ghosting by 45% for fast-scaling B2B tech without adding rep friction. Happy to send over a 2-page case study if relevant?', ARRAY['https://vanta.com/company', 'https://linkedin.com/in/steviecase'], 'Verified with Sources', ARRAY['Stevie Case leads global revenue & GTM', 'SOC 2 / ISO 27001 market leader', 'Buyers are CISOs with extreme calendar congestion'], ARRAY['Outbound AE ghost rate peaks when meetings booked >3 days out']),
('b0000000-0000-0000-0000-000000000003', 'ClickUp', 'https://clickup.com', 'B2B SaaS / Collaborative Work OS', 'All-in-one productivity and project management platform with AI-powered task workflows.', 'Inbound demo decay: high volume of freemium accounts book enterprise migration demos but ghost when meetings are set >48h out.', 'Matt Bauman, Global VP of Sales', 'Hi Matt, huge fan of ClickUp 3.0. With thousands of teams upgrading from free tiers to Enterprise, how does ClickUp prevent the dreaded 48-hour inbound demo decay? We engineered an automated calendar confirmation and prep sequence that cuts no-shows by half. Open to a 3-minute async Loom walkthrough?', ARRAY['https://clickup.com', 'https://linkedin.com/in/mattbauman-sales'], 'Verified with Sources', ARRAY['Launched ClickUp 3.0 platform', 'Freemium to enterprise upgrade motion is core focus', 'Global sales team across US & EMEA'], ARRAY['High freemium sign-ups lead to lower intent demo bookings']),
('b0000000-0000-0000-0000-000000000004', 'Apollo.io', 'https://apollo.io', 'B2B SaaS / Sales Intelligence & GTM Acceleration', 'Comprehensive lead intelligence, sequencing, and sales execution platform.', 'Outbound SDR-to-AE handoff friction leading to booked prospect ghosting before discovery calls.', 'Adam Carr, Chief Revenue Officer', 'Hi Adam, congrats on Apollo''s explosive GTM trajectory. Even with stellar sequence automation, SDR-booked discovery calls often leak 30-50% between invite and Zoom. We plug into Apollo to automate pre-meeting prospect intent checks and calendar hold confirmations. Would you be open to comparing notes?', ARRAY['https://apollo.io', 'https://linkedin.com/in/adamcarr-gtm'], 'Verified with Sources', ARRAY['Unicorn GTM platform with massive SDR user base', 'Adam Carr joined as CRO', 'Internal dogfooding of sales tools'], ARRAY['High outbound volume creates handoff drop-offs']),
('b0000000-0000-0000-0000-000000000005', 'PostHog', 'https://posthog.com', 'B2B SaaS / Developer Product Analytics & DevTools', 'All-in-one developer platform for product analytics, session recording, feature flags, and A/B testing.', 'Enterprise/VPC migration drop-off: developer leads book technical discussions but skip if they lack immediate transparent setup specs.', 'James Hawkins, Co-founder & Co-CEO', 'Hi James, love PostHog''s radical transparency and developer-first culture. Noticed engineering teams transitioning to custom VPC deployments sometimes hesitate at the technical evaluation stage. We built a zero-BS, markdown-native pre-meeting architecture briefing tool that lets engineers review specs before jumping on a call. Thought you might find the approach interesting.', ARRAY['https://posthog.com/handbook', 'https://github.com/posthog'], 'Verified with Sources', ARRAY['James Hawkins Co-founder & CEO', 'Public handbook and open-source pricing', 'Developers hate generic sales calls'], ARRAY['VPC and Enterprise migrations require deep technical pre-reads'])
INSERT INTO leads (id, business_name, website, contact_person, business_problem, outreach_status, last_action_date, next_follow_up_date, priority, next_action, reason_for_priority) VALUES
('l0000000-0000-0000-0000-000000000001', 'ClickUp', 'https://clickup.com', 'Matt Bauman, Global VP of Sales', 'Inbound demo decay: high volume of freemium accounts book enterprise migration demos but ghost when meetings are set >48h out.', 'Meeting Booked', CURRENT_DATE - INTERVAL '1 day', CURRENT_DATE, 'High', 'Deploy Pre-Demo Show-Up Safeguard: Send calendar agenda with 1-click reschedule options & 90-sec preview video.', 'Active meeting booked for today! Highest immediate revenue risk; converting this meeting preserves a potential $30k+ enterprise pilot.'),
('l0000000-0000-0000-0000-000000000002', 'Customer.io', 'https://customer.io', 'Chris Parker, VP of Global Sales', 'High sales engineering capacity waste from mid-market demo no-shows during competitive evaluation against Braze/Iterable.', 'Contacted', CURRENT_DATE - INTERVAL '2 days', CURRENT_DATE + INTERVAL '1 day', 'High', 'Send Value-Add Follow-Up #1: Share 60-sec interactive demo show-up rate benchmark tailored to messaging SaaS.', 'Tier-1 ICP; large sales org; high ACV ($15k-$60k); high cost per wasted sales engineer demo slot.'),
('l0000000-0000-0000-0000-000000000003', 'Vanta', 'https://vanta.com', 'Stevie Case, Chief Revenue Officer', 'Severe drop-off between demo booking and attendance among time-strapped CISOs and Heads of Engineering.', 'Followed Up', CURRENT_DATE - INTERVAL '3 days', CURRENT_DATE - INTERVAL '1 day', 'High', 'Send Multi-Channel LinkedIn InMail referencing recent enterprise compliance velocity benchmarks.', 'Overdue follow-up! Rapid enterprise expansion; aggressive GTM targets; CRO prioritizes AE pipeline conversion efficiency.'),
('l0000000-0000-0000-0000-000000000004', 'Apollo.io', 'https://apollo.io', 'Adam Carr, Chief Revenue Officer', 'Outbound SDR-to-AE handoff friction leading to booked prospect ghosting before discovery calls.', 'Contacted', CURRENT_DATE - INTERVAL '3 days', CURRENT_DATE + INTERVAL '2 days', 'Medium', 'Send Follow-Up #2 with data snippet on SDR-to-AE pipeline conversion benchmarks.', 'Strong ICP and massive rep volume, but internal tooling density means sales cycle may require deeper RevOps integration proof.'),
('l0000000-0000-0000-0000-000000000005', 'PostHog', 'https://posthog.com', 'James Hawkins, Co-founder & Co-CEO', 'Enterprise/VPC migration drop-off: developer leads book technical discussions but skip if they lack immediate transparent setup specs.', 'Contacted', CURRENT_DATE - INTERVAL '4 days', CURRENT_DATE + INTERVAL '3 days', 'Medium', 'Monitor public GitHub discussion & send gentle email follow-up with open-source workflow integration repo.', 'Non-traditional sales motion (PLG/developer focus); high strategic value and brand prestige, but longer sales qualification cycle requiring technical nuance.'),
('l0000000-0000-0000-0000-000000000006', 'Ramp', 'https://ramp.com', 'Colin Kennedy, Chief Business Officer', 'Finance team demo no-shows due to end-of-month accounting closes.', 'Not Started', CURRENT_DATE - INTERVAL '5 days', CURRENT_DATE - INTERVAL '2 days', 'High', 'Execute initial cold email referencing automated spend governance sync.', 'High ACV fintech; overdue outreach task; executive calendar requires immediate touchpoint.'),
('l0000000-0000-0000-0000-000000000007', 'Loom', 'https://loom.com', 'Nicole Herskowitz, VP Marketing', 'Asynchronous evaluation drop-offs after initial self-serve signup.', 'Demo Attended', CURRENT_DATE - INTERVAL '1 day', CURRENT_DATE + INTERVAL '2 days', 'Medium', 'Deliver customized 3-tier enterprise rollout proposal.', 'Already completed demo; active buyer intent; moving toward closing phase.')
